private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // Both null -> true
    if (str == null) {
        return prefix == null;
    }
    // str non-null, prefix null -> false
    if (prefix == null) {
        return false;
    }
    // prefix longer than str cannot match
    if (prefix.length() > str.length()) {
        return false;
    }
    // Use regionMatches for case-sensitive or insensitive comparison
    return str.regionMatches(ignoreCase, 0, prefix, 0, prefix.length());
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null) {
        return prefix == null;
    }
    if (prefix == null) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    }
    return str.startsWith(prefix);
}

